function showNodeProbeResult(path,node,result){const dialog=document.createElement('dialog');dialog.className='editor-dialog preview-dialog';const box=document.createElement('div');box.className='card';const heading=document.createElement('h2');heading.textContent=`Диагностическая проверка: ${node.external_name}`;const intro=document.createElement('p');intro.className='muted';intro.textContent=`${path.modem_name} → ${path.subscription_name}. Результат не меняет authoritative-состояние или активный путь.`;const transport=card('Транспорт',result.node?.transport?.state||result.transport_state,`${result.node?.transport?.latency_ms||0} ms · ${result.node?.transport?.error_code||'без ошибки'}`);const targets=result.node?.targets||[];const close=()=>dialog.close();box.append(heading,intro,transport,table([{label:'Ресурс',key:'target_id'},{label:'Обязательный',render:x=>x.required?'Да':'Нет'},{label:'Состояние',render:x=>badge(x.state)},{label:'HTTP',render:x=>x.http_status||'—'},{label:'Задержка',render:x=>x.latency_ms?`${x.latency_ms} ms`:'—'},{label:'Причина',key:'error_code'}],targets),actionGroup(actionButton('Закрыть',close)));dialog.append(box);dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal()}
async function openNodeTargetEvidence(path,node){const dialog=document.createElement('dialog');dialog.className='editor-dialog preview-dialog';const box=document.createElement('div');box.className='card';const heading=document.createElement('h2');heading.textContent=`Результаты ресурсов: ${node.external_name}`;const intro=document.createElement('p');intro.className='muted';intro.textContent=`Данные загружаются страницами по 50 записей. Старые policy/route generations всегда помечаются STALE.`;const pages=document.createElement('div');pages.className='evidence-pages';const controls=document.createElement('div');controls.className='actions';let cursor='';const load=async()=>{const suffix=cursor?`&cursor=${encodeURIComponent(cursor)}`:'';const data=await api(`/api/v1/paths/${encodeURIComponent(path.id)}/nodes/${encodeURIComponent(node.node_id)}/targets?limit=50${suffix}`);pages.append(table([{label:'Приоритет',key:'priority'},{label:'Ресурс',key:'name'},{label:'Обязательный',render:x=>x.required?'Да':'Нет'},{label:'Состояние',render:x=>badge(x.state)},{label:'HTTP',render:x=>x.http_status||'—'},{label:'Задержка',render:x=>x.latency_ms?`${x.latency_ms} ms`:'—'},{label:'Причина',key:'error_code'},{label:'Проверено',key:'checked_at'},{label:'Истекает',key:'expires_at'}],data.items));cursor=data.next_cursor||'';controls.replaceChildren();if(cursor)controls.append(actionButton('Загрузить ещё',load));controls.append(actionButton('Закрыть',()=>dialog.close()))};box.append(heading,intro,pages,controls);dialog.append(box);dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal();await load()}
