async function renderMatchers(){const data=await api('/api/v1/node-matchers');const enabled=data.items.filter(item=>item.Enabled).sort((a,b)=>a.Priority-b.Priority);const reorder=async(id,delta)=>{const ids=enabled.map(item=>item.ID),index=ids.indexOf(id),next=index+delta;if(index<0||next<0||next>=ids.length)return;[ids[index],ids[next]]=[ids[next],ids[index]];await api('/api/v1/node-matchers/priorities',{method:'PUT',body:JSON.stringify({ids})});notice('Порядок правил обновлён, пути поставлены на перепроверку');await renderMatchers()};const edit=item=>{const dialog=document.createElement('dialog');dialog.className='editor-dialog';const close=()=>dialog.close();dialog.append(matcherSettingsForm(item,async payload=>{close();await previewMatcherChange(item,payload)},close));dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal()};const rows=data.items.map(item=>({...item,actions:actionGroup(actionButton('↑',()=>reorder(item.ID,-1),false,!item.Enabled||enabled[0]?.ID===item.ID),actionButton('↓',()=>reorder(item.ID,1),false,!item.Enabled||enabled.at(-1)?.ID===item.ID),actionButton('Изменить',()=>edit(item)),actionButton(item.Enabled?'Отключить':'Включить',()=>previewMatcherChange(item,{pattern:item.Pattern,type:item.Type,enabled:!item.Enabled})),actionButton('Удалить',async()=>{if(!confirm(`Удалить правило «${item.Pattern}»?`))return;await api(`/api/v1/node-matchers/${encodeURIComponent(item.ID)}`,{method:'DELETE'});notice('Правило удалено, candidate pools пересчитаны');await renderMatchers()},true))}));setContent(matcherSettingsForm(null,payload=>previewMatcherChange(null,payload)),table([{label:'Приоритет',key:'Priority'},{label:'Шаблон',key:'Pattern'},{label:'Тип',key:'Type'},{label:'Включено',render:item=>item.Enabled?'Да':'Нет'},{label:'Действия',render:item=>item.actions}],rows))}
