async function renderRemote(){const [status,settings]=await Promise.all([api('/api/v1/wireguard/status'),api('/api/v1/settings/wireguard')]);const grid=document.createElement('div');grid.className='grid';grid.append(card('WireGuard',status.status,settings.configured?(settings.endpoint||'Endpoint настроен'):'Требуется настройка'),card('Текущий модем',status.current_modem_id||'—',status.candidate_modem_id?`Проверяется: ${status.candidate_modem_id}`:'Нет кандидата'),card('Последний handshake',status.last_handshake_at||'—',status.handshake_stale?`Внимание: handshake устарел (${status.handshake_age_seconds}s)`:status.endpoint_ip||'Endpoint IP неизвестен'),card('Маршрут endpoint',status.route_modem_id||'—','Независим от VPN-пути'));const form=document.createElement('form');form.className='card settings-form';form.innerHTML='<h2>Management WireGuard</h2><p class="muted">Private key сохраняется только в защищённом файле и никогда не возвращается Web API. Оставьте поле пустым, чтобы сохранить действующий ключ.</p><label>VPS endpoint<input name="endpoint" placeholder="203.0.113.10:51821" required></label><label>Public key VPS<input name="peer" autocomplete="off" required></label><label>Private key Gateway<input name="private" type="password" autocomplete="new-password" placeholder="Оставить действующий или вставить новый"></label><label>Persistent keepalive, секунд<input name="keepalive" type="number" min="10" max="60" value="25" required></label><label>Ожидание handshake, секунд<input name="handshake" type="number" min="30" max="180" value="45" required></label><button>Сохранить и начать проверку</button>';form.elements.endpoint.value=settings.endpoint||'';form.elements.peer.value=settings.peer_public_key||'';form.elements.keepalive.value=settings.persistent_keepalive||25;form.elements.handshake.value=settings.handshake_timeout_seconds||45;form.addEventListener('submit',async e=>{e.preventDefault();if(!confirm('Новая конфигурация может временно прервать удалённый доступ. Сохранить?'))return;const data=new FormData(form);try{const result=await api('/api/v1/settings/wireguard',{method:'PUT',body:JSON.stringify({endpoint:data.get('endpoint'),peer_public_key:data.get('peer'),private_key:data.get('private'),persistent_keepalive:Number(data.get('keepalive')),handshake_timeout_seconds:Number(data.get('handshake'))})});form.elements.private.value='';notice(result.sync_state==='RETRY_PENDING'?'Настройки сохранены; автомат повторит подключение':'Настройки сохранены, начата проверка handshake');await renderRemote()}catch(err){notice(err.message)}});setContent(grid,table([{label:'№',key:'number'},{label:'Модем',key:'name'},{label:'Приоритет',key:'priority'},{label:'Состояние модема',render:x=>badge(x.state)},{label:'Доступ к VPS',render:x=>badge(x.management_reachability_state)}],status.modems),form)}
async function renderNetwork(){const data=await api('/api/v1/settings/network');const grid=document.createElement('div');grid.className='grid';grid.append(card('LAN-интерфейс',data.interface_name,'Transit к Keenetic'),card('Текущий адрес',data.lan_address,'IPv4, safe apply'));const nodes=[grid];const pending=parseNetworkConfirmation();if(pending){const box=document.createElement('div');box.className='card';const h=document.createElement('h2');h.textContent='Подтвердить новый адрес';const p=document.createElement('p');p.textContent='Эта страница открыта через новый адрес Gateway. Подтверждение удалит старый адрес и отменит автоматический rollback.';const button=document.createElement('button');button.textContent='Подтвердить сетевые настройки';button.addEventListener('click',async()=>{try{await api(`/api/v1/settings/network/apply/${encodeURIComponent(pending.id)}/confirm`,{method:'POST',body:JSON.stringify({confirm_token:pending.token})});history.replaceState(null,'',location.pathname);notice('Сетевые настройки подтверждены');await renderNetwork()}catch(err){notice(err.message)}});box.append(h,p,button);nodes.push(box)}if(data.active_apply&&data.active_apply.apply_id){nodes.push(card('Активная транзакция',data.active_apply.state,`${data.active_apply.apply_id} · rollback ${data.active_apply.rollback_deadline}`))}const form=document.createElement('form');form.className='toolbar';form.innerHTML='<label>Новый LAN CIDR<input name="lan" placeholder="192.168.210.1/24" required></label><button>Применить с rollback</button>';form.addEventListener('submit',async e=>{e.preventDefault();if(!confirm('Новый адрес будет применён на 60 секунд. Продолжить?'))return;const value=new FormData(form).get('lan');try{const result=await api('/api/v1/settings/network/apply',{method:'POST',body:JSON.stringify({lan_address:value})});const box=document.createElement('div');box.className='card';const h=document.createElement('h2');h.textContent='Сетевая транзакция запущена';const p=document.createElement('p');p.textContent=`Rollback deadline: ${result.rollback_deadline}`;const link=document.createElement('a');link.className='button-link';link.textContent='Открыть новый адрес и подтвердить';const destination=new URL(result.new_url);destination.hash=`network-confirm=${result.apply_id}.${result.confirm_token}`;link.href=destination.toString();box.append(h,p,link);setContent(box)}catch(err){notice(err.message)}});nodes.push(form);setContent(...nodes)}
function parseNetworkConfirmation(){const params=new URLSearchParams(location.hash.slice(1));const value=params.get('network-confirm')||'';const dot=value.indexOf('.');if(dot<1)return null;const id=value.slice(0,dot),token=value.slice(dot+1);if(!/^apply-[a-f0-9]{32}$/.test(id)||!/^[a-f0-9]{64}$/.test(token))return null;return{id,token}}
