async function loggingJournalViewer(components){const box=document.createElement('div');box.className='card journal-viewer';const heading=document.createElement('h2');heading.textContent='Технический журнал';const note=document.createElement('p');note.className='muted';note.textContent='Только namespace Gateway VPN. Фильтры проверяются сервером; сообщения повторно проходят redaction и выдаются страницами до 25 записей.';const form=document.createElement('form');form.className='toolbar journal-filters';form.innerHTML='<label>От<input name="since" type="datetime-local"></label><label>Уровень<select name="level"><option value="">Все</option><option value="error">Error</option><option value="warning">Warning</option><option value="info">Info</option><option value="debug">Debug</option></select></label><label>Компонент<select name="component"><option value="">Все</option></select></label><label>Модем<input name="modem_id" maxlength="128" placeholder="modem-id"></label><label>Подписка<input name="subscription_id" maxlength="128" placeholder="subscription-id"></label><label>Путь<input name="path_id" maxlength="128" placeholder="path-id"></label><label>Correlation ID<input name="correlation_id" maxlength="128"></label><label>Текст<input name="search" maxlength="128"></label><button>Применить</button>';components.forEach(component=>{const option=document.createElement('option');option.value=component;option.textContent=loggingComponentLabels[component]||component;form.elements.component.append(option)});const initial=new Date(Date.now()-24*60*60*1000);form.elements.since.value=new Date(initial.getTime()-initial.getTimezoneOffset()*60000).toISOString().slice(0,16);const pages=document.createElement('div');pages.className='journal-pages';const controls=document.createElement('div');controls.className='actions';let cursor='';const load=async(reset=true)=>{const params=new URLSearchParams({limit:'25'});const since=form.elements.since.value;if(since)params.set('since',new Date(since).toISOString());for(const name of ['level','component','modem_id','subscription_id','path_id','correlation_id','search']){const value=form.elements[name].value.trim();if(value)params.append(name,value)}if(!reset&&cursor)params.set('cursor',cursor);const page=await api('/api/v1/logs?'+params.toString());const rows=page.items.map(item=>({...item,severityBadge:badge(item.severity),scope:[item.modem_id,item.subscription_id,item.path_id].filter(Boolean).join(' · ')||'—'}));const current=table([{label:'Время',key:'occurred_at'},{label:'Уровень',render:item=>item.severityBadge},{label:'Компонент',render:item=>loggingComponentLabels[item.component]||item.component},{label:'Unit',key:'unit'},{label:'Scope',key:'scope'},{label:'Correlation',key:'correlation_id'},{label:'Сообщение',key:'message'},{label:'Повторы',key:'suppressed_repeats'}],rows);pages.className='journal-pages';if(reset)pages.replaceChildren(current);else pages.append(current);cursor=page.next_cursor||'';controls.replaceChildren();if(page.has_more&&cursor)controls.append(actionButton('Загрузить более старые',()=>load(false)))};form.addEventListener('submit',async event=>{event.preventDefault();try{await load(true)}catch(err){notice(err.message)}});box.append(heading,note,form,pages,controls);try{await load(true)}catch(err){pages.className='empty';pages.textContent=err.message}return box}
async function renderSystem(){const data=await api('/api/v1/settings/logging');const remaining=data.debug_remaining_seconds?`${Math.ceil(data.debug_remaining_seconds/60)} мин · до ${data.debug_until}`:'Выключен';const grid=document.createElement('div');grid.className='grid';grid.append(card('Общий уровень',data.global_level,'Production policy'),card('Временный debug',remaining,'Автоматически отключается и переживает reboot'),card('Хранение',`${data.retention_days} дней`,`${bytes(data.max_disk_usage_bytes)} · ${data.retention_apply_state}`),card('Audit','Не ниже INFO','Нельзя отключить настройками'));const form=document.createElement('form');form.className='card settings-form logging-editor';const heading=document.createElement('h2');heading.textContent='Логирование';const intro=document.createElement('p');intro.className='muted';intro.textContent='Все записи проходят secret redaction до logger. Debug включается только на срок от 5 минут до 24 часов. Payload подписок, proxy credentials, response bodies и полные Mihomo configs не журналируются.';form.append(heading,intro);const globalLabel=document.createElement('label');globalLabel.textContent='Общий уровень';const globalSelect=loggingLevelSelect(data.global_level);globalSelect.name='global_level';globalSelect.querySelector('option[value="inherit"]').remove();globalLabel.append(globalSelect);form.append(globalLabel);const componentHeading=document.createElement('h3');componentHeading.textContent='Уровни компонентов';form.append(componentHeading);data.available_components.forEach(component=>{const label=document.createElement('label');label.textContent=loggingComponentLabels[component]||component;const select=loggingLevelSelect(data.component_levels[component],component==='auth_audit');select.dataset.component=component;label.append(select);const effective=document.createElement('span');effective.className='muted';effective.textContent=`Сейчас: ${data.effective_levels[component]}`;label.append(effective);form.append(label)});const debugField=document.createElement('fieldset');debugField.className='settings-group';const debugLegend=document.createElement('legend');debugLegend.textContent='Временный debug';debugField.append(debugLegend);data.available_components.forEach(component=>{const label=document.createElement('label');label.className='check';const input=document.createElement('input');input.type='checkbox';input.dataset.debugComponent=component;input.checked=data.debug_components.includes(component);label.append(input,document.createTextNode(loggingComponentLabels[component]||component));debugField.append(label)});const ttlLabel=document.createElement('label');ttlLabel.textContent='Срок debug, минут';const ttl=document.createElement('input');ttl.type='number';ttl.name='debug_ttl_minutes';ttl.min=Math.ceil(data.minimum_debug_ttl_seconds/60);ttl.max=Math.floor(data.maximum_debug_ttl_seconds/60);ttl.value=data.debug_remaining_seconds?Math.max(Number(ttl.min),Math.ceil(data.debug_remaining_seconds/60)):15;ttlLabel.append(ttl);debugField.append(ttlLabel);form.append(debugField);const retentionHeading=document.createElement('h3');retentionHeading.textContent='Хранение и агрегация';form.append(retentionHeading);const numeric=(labelText,name,value,min,max)=>{const label=document.createElement('label');label.textContent=labelText;const input=document.createElement('input');input.type='number';input.name=name;input.value=value;input.min=min;input.max=max;input.required=true;label.append(input);form.append(label);return input};numeric('Хранение, дней','retention_days',data.retention_days,1,365);numeric('Максимум журнала, MiB','max_disk_mib',Math.round(data.max_disk_usage_bytes/1048576),64,4096);numeric('Diagnostic excerpt, KiB','excerpt_kib',Math.round(data.diagnostic_excerpt_bytes/1024),64,16384);numeric('Окно агрегации health errors, секунд','aggregation_seconds',data.health_error_aggregation_seconds,1,3600);const retentionHeadingState=data.retention_apply_state==='APPLIED'?'Retention policy применена к namespaced journald.':data.retention_apply_state==='FAILED'?`Синхронизация journald не удалась: ${data.retention_last_error_code||'UNKNOWN'}. Автоматический worker повторит попытку.`:data.retention_apply_state==='PENDING'||data.retention_apply_state==='APPLYING'?'Retention policy ожидает применения root broker; автоматический worker повторяет синхронизацию.':'До первой подтверждённой синхронизации действует безопасный installer default.';const retentionNote=document.createElement('p');retentionNote.className='muted';retentionNote.textContent=retentionHeadingState;form.append(retentionNote);const submit=document.createElement('button');submit.type='submit';submit.textContent='Сохранить настройки';form.append(submit);form.addEventListener('submit',async event=>{event.preventDefault();const componentLevels={};form.querySelectorAll('select[data-component]').forEach(select=>{if(select.value!=='inherit')componentLevels[select.dataset.component]=select.value});const debugComponents=[...form.querySelectorAll('input[data-debug-component]:checked')].map(input=>input.dataset.debugComponent);if(debugComponents.length&&!data.debug_components.length&&!confirm('Временно включить подробный debug? Secret redaction останется обязательным, а debug автоматически отключится по TTL.'))return;const payload={global_level:globalSelect.value,component_levels:componentLevels,debug_components:debugComponents,debug_ttl_seconds:debugComponents.length?Number(ttl.value)*60:0,retention_days:Number(form.elements.retention_days.value),max_disk_usage_bytes:Number(form.elements.max_disk_mib.value)*1048576,diagnostic_excerpt_bytes:Number(form.elements.excerpt_kib.value)*1024,health_error_aggregation_seconds:Number(form.elements.aggregation_seconds.value)};submit.disabled=true;try{const result=await api('/api/v1/settings/logging',{method:'PUT',body:JSON.stringify(payload)});notice(result.retention_apply_state==='APPLIED'?'Настройки и journald retention применены':'Настройки уровней применены; retention будет повторно синхронизирован');await renderSystem()}catch(err){notice(err.message);submit.disabled=false}});const journal=await loggingJournalViewer(data.available_components);setContent(grid,form,journal)}
async function downloadDiagnosticBundle(){const response=await fetch('/api/v1/system/diagnostics',{method:'POST',credentials:'same-origin',headers:{'Accept':'application/zip','X-CSRF-Token':state.csrf}});if(response.status===401){showLogin();throw new Error('Требуется вход')}if(!response.ok){let message=`HTTP ${response.status}`;try{message=(await response.json()).error.message}catch{}throw new Error(message)}const maximum=32*1024*1024,declared=Number(response.headers.get('Content-Length')||0);if(declared>maximum)throw new Error('Диагностический архив превысил допустимый размер');const blob=await response.blob();if(!blob.size||blob.size>maximum)throw new Error('Получен некорректный диагностический архив');const disposition=response.headers.get('Content-Disposition')||'',match=disposition.match(/filename="(gateway-vpn-diagnostics-[0-9TZ]+\.zip)"/),filename=match?.[1]||'gateway-vpn-diagnostics.zip',url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.hidden=true;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),0);const complete=response.headers.get('X-Diagnostic-Complete')==='true',digest=response.headers.get('X-Content-SHA256')||'';notice(`${complete?'Полный':'Частичный'} диагностический архив создан · ${bytes(blob.size)}${digest?` · SHA-256 ${digest.slice(0,12)}…`:''}`)}
async function diagnosticBundlePanel(){const box=document.createElement('div');box.className='card diagnostic-bundle';const heading=document.createElement('h2');heading.textContent='Диагностический архив';try{const data=await api('/api/v1/gateway/diagnostics');const note=document.createElement('p');note.className='muted';note.textContent='ZIP создаётся только в памяти. Секреты, ключи, токены и полные payload подписок исключены; каждый файл имеет SHA-256 в manifest.json.';const details=document.createElement('p');details.className='muted';details.textContent=`Журнал: до ${bytes(data.configured_journal_excerpt_bytes)} · архив: до ${bytes(data.maximum_archive_bytes)} · ${data.sections.length} разделов`;box.append(heading,note,details,actionGroup(actionButton('Создать и скачать',downloadDiagnosticBundle,false,!data.available)))}catch(err){const error=document.createElement('p');error.className='muted';error.textContent=`Диагностический архив недоступен: ${err.message}`;box.append(heading,error)}return box}
async function createLocalDatabaseSnapshot(){if(!confirm('Создать проверенный локальный снимок SQLite? Он хранится на Gateway и не заменяет зашифрованную внешнюю копию.'))return;const item=await api('/api/v1/system/backups/snapshot',{method:'POST'});notice(`Локальный снимок № ${item.snapshot_id.slice(-12)} создан · ${bytes(item.bytes)} · integrity PASS`);await renderSystemWithDiagnostics()}
async function downloadPortableBackup(passphrase,confirmation){const response=await fetch('/api/v1/system/backup',{method:'POST',credentials:'same-origin',headers:{'Accept':'application/vnd.gateway-vpn.backup','Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify({passphrase,passphrase_confirmation:confirmation})});if(response.status===401){showLogin();throw new Error('Требуется вход')}if(!response.ok){let message=`HTTP ${response.status}`;try{message=(await response.json()).error.message}catch{}throw new Error(message)}const maximum=300*1024*1024,declared=Number(response.headers.get('Content-Length')||0);if(!declared||declared>maximum)throw new Error('Некорректный размер зашифрованной копии');const blob=await response.blob();if(blob.size!==declared)throw new Error('Зашифрованная копия получена не полностью');const disposition=response.headers.get('Content-Disposition')||'',match=disposition.match(/filename="(gateway-vpn-backup-[0-9TZ]+-[a-f0-9]{24}\.gvpn)"/),filename=match?.[1]||'gateway-vpn-backup.gvpn',url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.hidden=true;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),0);const digest=response.headers.get('X-Content-SHA256')||'';notice(`Зашифрованная резервная копия создана · ${bytes(blob.size)}${digest?` · SHA-256 ${digest.slice(0,12)}…`:''}`)}
async function restoreJSONResponse(response){if(response.status===401){showLogin();throw new Error('Требуется вход')}if(!response.ok){let message=`HTTP ${response.status}`;try{message=(await response.json()).error.message}catch{}throw new Error(message)}if(response.status===204)return null;return response.json()}
async function stagePortableRestore(file,passphrase){if(!file||!file.name.toLowerCase().endsWith('.gvpn'))throw new Error('Выберите файл Gateway VPN с расширением .gvpn');if(!file.size||file.size>300*1024*1024)throw new Error('Размер .gvpn должен быть от 1 байта до 300 MiB');const body=new FormData();body.append('passphrase',passphrase);body.append('backup',file,file.name);const response=await fetch('/api/v1/system/restore',{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json','X-CSRF-Token':state.csrf},body});return restoreJSONResponse(response)}
async function discardStagedRestore(operation){if(!confirm(`Удалить проверенный staging ${operation.restore_id}? Live-конфигурация не изменится.`))return;await api('/api/v1/system/restore',{method:'DELETE',headers:{'X-Confirm-Destructive':'discard-staged-restore'},body:JSON.stringify({restore_id:operation.restore_id})});notice('Staged restore удалён; live-состояние не изменялось');await renderSystemWithDiagnostics()}
async function applyStagedRestore(operation){const message=`Restore ${operation.restore_id} запущен или запускается. После проверки все прежние сессии будут отозваны; войдите снова после восстановления управления.`;sessionStorage.setItem('gateway-vpn-restore-reconnect',message);try{const result=await api('/api/v1/system/restore/apply',{method:'POST',headers:{'X-Confirm-Destructive':'apply-verified-restore'},body:JSON.stringify({restore_id:operation.restore_id})});notice(`${message} Страница перезагрузится через 8 секунд.`);setTimeout(()=>location.reload(),8000);return result}catch(err){notice(`${message} Соединение прервано до ответа; страница перезагрузится через 12 секунд.`);setTimeout(()=>location.reload(),12000);throw err}}
async function restorePanel(stagingAvailable,applyAvailable){const section=document.createElement('section');section.className='restore-panel';const heading=document.createElement('h3');heading.textContent='Восстановление из .gvpn';section.append(heading);if(!stagingAvailable){const unavailable=document.createElement('p');unavailable.className='muted';unavailable.textContent='Проверка и staging restore не подключены.';section.append(unavailable);return section}const status=await api('/api/v1/system/restore');if(status.pending){const operation=status.operation||{};const warning=document.createElement('p');warning.className='restore-warning';warning.textContent=operation.state==='APPLY_REQUESTED'?'Применение было явно подтверждено и ожидает root helper. При ошибке запуска можно безопасно повторить Apply; удалить staging до rollback нельзя.':'Файл расшифрован только во временном защищённом staging, полностью проверен и ещё не менял live-состояние. Перезагрузка не применит его без отдельного подтверждения.';const summary=document.createElement('dl');summary.className='restore-summary';for(const [label,value] of [['Restore ID',operation.restore_id],['Snapshot',operation.snapshot_id],['Schema',operation.schema_version],['Gateway',operation.gateway_version],['Зашифрованный файл',bytes(operation.portable_bytes)],['Payload',bytes(operation.payload_bytes)],['SHA-256',operation.portable_sha256],['Состояние',operation.state],['Последняя ошибка',operation.apply_error_code||'—']]){const term=document.createElement('dt');term.textContent=label;const detail=document.createElement('dd');detail.textContent=String(value??'—');summary.append(term,detail)}const actions=document.createElement('div');actions.className='restore-actions';const confirmation=document.createElement('label');confirmation.textContent='Для применения введите ВОССТАНОВИТЬ';const input=document.createElement('input');input.autocomplete='off';input.spellcheck=false;input.maxLength=20;confirmation.append(input);const apply=actionButton('Применить и перезапустить управление',async()=>{if(input.value!=='ВОССТАНОВИТЬ'){notice('Введите ВОССТАНОВИТЬ точно, как показано');return}if(!confirm('Будут заменены DB, config, secrets, subscriptions, TLS и Mihomo state. Старое состояние сохранится в pre-restore snapshot. Продолжить?'))return;apply.disabled=true;discard.disabled=true;try{await applyStagedRestore(operation)}catch(err){notice(err.message);apply.disabled=false;discard.disabled=operation.state!=='STAGED'}},true,!applyAvailable||!status.apply_available);const discard=actionButton('Удалить staging',()=>discardStagedRestore(operation),true,operation.state!=='STAGED');actions.append(confirmation,apply,discard);section.append(warning,summary,actions);return section}const form=document.createElement('form');form.className='settings-form restore-upload-form';form.innerHTML='<label>Зашифрованная копия .gvpn<input name="backup" type="file" accept=".gvpn,application/vnd.gateway-vpn.backup" required></label><label>Passphrase<input name="passphrase" type="password" autocomplete="current-password" minlength="12" maxlength="256" required></label><button>Загрузить и полностью проверить</button><p class="muted">До отдельного подтверждения live-файлы не изменяются. Upload и passphrase удаляются сразу после проверки; сохраняется только verified staging.</p>';form.addEventListener('submit',async event=>{event.preventDefault();const file=form.elements.backup.files[0],passphrase=form.elements.passphrase.value,button=form.querySelector('button');button.disabled=true;try{const operation=await stagePortableRestore(file,passphrase);form.reset();notice(`Restore ${operation.restore_id} проверен и помещён в staging; live-состояние не изменено`);await renderSystemWithDiagnostics()}catch(err){notice(err.message);form.elements.passphrase.value=''}finally{button.disabled=false}});section.append(form);return section}
async function backupSnapshotPanel(){const box=document.createElement('div');box.className='card backup-snapshots';const heading=document.createElement('h2');heading.textContent='Резервные снимки и восстановление';try{const data=await api('/api/v1/system/backups');const note=document.createElement('p');note.className='muted';note.textContent='SQLite снимается через Online Backup API и до ротации проходит quick_check, полный integrity_check, foreign keys и SHA-256. Локальные снимки не содержат отдельные secret-файлы.';const stateLine=document.createElement('p');stateLine.className='muted';stateLine.textContent=`Проверено: ${data.verified_count} · повреждено: ${data.invalid_count} · retention daily/manual: ${data.daily_retention}/${data.manual_retention}`;const portability=document.createElement('p');portability.className='muted';portability.textContent=data.portable_encrypted_backup_available?'Переносимая копия включает DB, конфигурацию, subscription payloads, TLS и другие secret-файлы только внутри шифрования AES-256-GCM; ключ выводится из passphrase Argon2id и не сохраняется.':'Зашифрованный переносимый backup ещё не подключён; локальный snapshot нельзя считать полной внешней копией.';const rows=(data.items||[]).slice(0,10).map(item=>({...item,status:item.verified?badge('VERIFIED'):badge(item.error_code||'INVALID')}));const snapshots=rows.length?table([{label:'Создан',key:'created_at'},{label:'Тип',key:'kind'},{label:'Schema',key:'schema_version'},{label:'Размер',render:item=>bytes(item.bytes)},{label:'SHA-256',render:item=>item.sha256?`${item.sha256.slice(0,12)}…`:'—'},{label:'Статус',render:item=>item.status}],rows):document.createElement('div');if(!rows.length){snapshots.className='empty';snapshots.textContent='Локальных снимков пока нет'}box.append(heading,note,stateLine,portability,actionGroup(actionButton('Создать локальный снимок',createLocalDatabaseSnapshot)),snapshots);if(data.portable_encrypted_backup_available){const form=document.createElement('form');form.className='settings-form portable-backup-form';form.innerHTML='<h3>Зашифрованная внешняя копия</h3><label>Passphrase (12–256 UTF-8 байт)<input name="passphrase" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><label>Повторите passphrase<input name="confirmation" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><button>Создать и скачать .gvpn</button><p class="muted">Потерянную passphrase восстановить невозможно. Храните файл и passphrase раздельно.</p>';form.addEventListener('submit',async event=>{event.preventDefault();const passphrase=form.elements.passphrase.value,confirmation=form.elements.confirmation.value;if(passphrase!==confirmation){notice('Passphrase не совпадают');return}const button=form.querySelector('button');button.disabled=true;try{await downloadPortableBackup(passphrase,confirmation);form.reset()}catch(err){notice(err.message)}finally{button.disabled=false}});box.append(form)}box.append(await restorePanel(data.restore_staging_available,data.restore_available))}catch(err){const error=document.createElement('p');error.className='muted';error.textContent=`Резервные снимки недоступны: ${err.message}`;box.append(heading,error)}return box}
async function stageSignedUpdate(file){if(!file||!file.name.toLowerCase().endsWith('.tar.gz'))throw new Error('Выберите подписанный Gateway VPN release с расширением .tar.gz');if(!file.size||file.size>768*1024*1024)throw new Error('Размер release archive должен быть от 1 байта до 768 MiB');const body=new FormData();body.append('release',file,file.name);const response=await fetch('/api/v1/system/update',{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json','X-CSRF-Token':state.csrf},body});return restoreJSONResponse(response)}
async function discardStagedUpdate(operation){if(!confirm(`Удалить verified release ${operation.gateway_version} из staging? Установленная версия не изменится.`))return;await api('/api/v1/system/update',{method:'DELETE',headers:{'X-Confirm-Destructive':'discard-staged-update'},body:JSON.stringify({update_id:operation.update_id})});notice('Staged release удалён; текущая версия не изменялась');await renderSystemWithDiagnostics()}
async function applyStagedUpdate(operation){const message=`Подписанное обновление до ${operation.gateway_version} запущено. Управление временно остановится; при ошибке binary и DB будут возвращены вместе.`;sessionStorage.setItem('gateway-vpn-update-reconnect',message);try{const result=await api('/api/v1/system/update/apply',{method:'POST',headers:{'X-Confirm-Destructive':'apply-verified-update'},body:JSON.stringify({update_id:operation.update_id})});notice(`${message} Страница перезагрузится через 12 секунд.`);setTimeout(()=>location.reload(),12000);return result}catch(err){notice(`${message} Соединение могло закрыться раньше HTTP-ответа; повторное подключение через 15 секунд.`);setTimeout(()=>location.reload(),15000);throw err}}
async function signedUpdatePanel(){const box=document.createElement('div');box.className='card signed-update';const heading=document.createElement('h2');heading.textContent='Подписанное обновление';box.append(heading);try{const status=await api('/api/v1/system/update');const note=document.createElement('p');note.className='muted';note.textContent='Release принимается только после Ed25519 signature, signer fingerprint, полного file manifest, SHA-256 и DB/config/API compatibility. Миграция выполняется на копии; rollback возвращает прежний binary и pre-update SQLite snapshot как одну пару.';box.append(note);if(status.pending){const operation=status.operation||{};const warning=document.createElement('p');warning.className='restore-warning';warning.textContent='Release проверен и находится только в staging. Live binary, DB и data path ещё не изменены.';const summary=document.createElement('dl');summary.className='restore-summary';for(const [label,value] of [['Update ID',operation.update_id],['Gateway',operation.gateway_version],['Mihomo',operation.mihomo_version],['Signer SHA-256',operation.signer_key_sha256],['Manifest SHA-256',operation.manifest_sha256],['Файлов',operation.file_count],['Размер',bytes(operation.uncompressed_bytes)],['Состояние',operation.state]]){const term=document.createElement('dt');term.textContent=label;const detail=document.createElement('dd');detail.textContent=String(value??'—');summary.append(term,detail)}const actions=document.createElement('div');actions.className='restore-actions';const confirmation=document.createElement('label');confirmation.textContent='Для применения введите ОБНОВИТЬ';const input=document.createElement('input');input.autocomplete='off';input.spellcheck=false;input.maxLength=20;confirmation.append(input);const apply=actionButton('Применить подписанное обновление',async()=>{if(input.value!=='ОБНОВИТЬ'){notice('Введите ОБНОВИТЬ точно, как показано');return}if(!confirm(`Обновить Gateway VPN до ${operation.gateway_version}? Data path будет закрыт, управление перезапущено, а rollback snapshot сохранён минимум до конца stability window.`))return;apply.disabled=true;discard.disabled=true;try{await applyStagedUpdate(operation)}catch(err){notice(err.message);apply.disabled=false;discard.disabled=false}},true,!status.apply_available);const discard=actionButton('Удалить staging',()=>discardStagedUpdate(operation),true);actions.append(confirmation,apply,discard);box.append(warning,summary,actions);return box}const form=document.createElement('form');form.className='settings-form update-upload-form';form.innerHTML='<label>Подписанный release archive<input name="release" type="file" accept=".gz,application/gzip" required></label><button>Загрузить и проверить без установки</button><p class="muted">Принимается только immutable versioned .tar.gz. Неподписанный latest, неизвестный signer, symlink/path traversal, лишние файлы и несовместимая schema отклоняются до исполнения кандидата.</p>';form.addEventListener('submit',async event=>{event.preventDefault();const file=form.elements.release.files[0],button=form.querySelector('button');button.disabled=true;try{const operation=await stageSignedUpdate(file);form.reset();notice(`Release ${operation.gateway_version} проверен; signer ${operation.signer_key_sha256.slice(0,12)}…; live-состояние не изменено`);await renderSystemWithDiagnostics()}catch(err){notice(err.message)}finally{button.disabled=false}});box.append(form)}catch(err){const unavailable=document.createElement('p');unavailable.className='muted';unavailable.textContent=`Подписанные обновления недоступны: ${err.message}`;box.append(unavailable)}return box}
async function signedUpdateTransactionPanel(){const box=document.createElement('div');box.className='card signed-update-history';const heading=document.createElement('h2');heading.textContent='Последняя root-транзакция обновления';box.append(heading);try{const status=await api('/api/v1/system/update');state.cache.signedUpdateStatus=status;if(status.transaction_query_state!=='AVAILABLE'){const warning=document.createElement('p');warning.className='restore-warning';warning.textContent=status.transaction_query_state==='NOT_CONFIGURED'?'Root broker состояния обновлений не настроен.':'Root-owned журнал обновления временно недоступен; staging-статус не доказывает результат установки.';box.append(warning);return box}const transaction=status.transaction||{};if(!transaction.exists){const empty=document.createElement('p');empty.className='muted';empty.textContent='Завершённых или выполняющихся root-транзакций обновления ещё нет.';box.append(empty);return box}const labels={PREPARED:'Подготовка',QUIESCED:'Сервисы остановлены',CANDIDATE_READY:'Кандидат проверен',DATABASE_SWITCH_PENDING:'Переключение БД начато',DATABASE_SWITCHED:'БД переключена',RELEASE_SWITCH_PENDING:'Переключение release начато',SWITCHED:'Release переключён',HEALTH_CHECKING:'Проверка здоровья',STABILIZING:'Период стабилизации',ROLLING_BACK:'Выполняется rollback',ROLLED_BACK:'Выполнен rollback',ROLLBACK_FAILED:'Rollback не завершён',FINALIZED:'Обновление подтверждено'};const formatTime=value=>value?new Date(value).toLocaleString('ru-RU'):'—';const summary=document.createElement('dl');summary.className='restore-summary';for(const [label,value] of [['Update ID',transaction.update_id],['Переход',`${transaction.old_version||'—'} → ${transaction.new_version||'—'}`],['Состояние',labels[transaction.state]||transaction.state],['Начато',formatTime(transaction.started_at)],['Обновлено',formatTime(transaction.updated_at)],['Stability deadline',formatTime(transaction.stability_deadline)],['Код результата',transaction.error_code||'—']]){const term=document.createElement('dt');term.textContent=label;const detail=document.createElement('dd');detail.textContent=String(value??'—');summary.append(term,detail)}const message=document.createElement('p');if(transaction.state==='FINALIZED'){message.className='muted';message.textContent='Новая версия прошла health-check и полный stability window.'}else if(transaction.state==='STABILIZING'){message.className='restore-warning';message.textContent='Новая версия активна, но rollback snapshot сохраняется до окончания stability window.'}else if(transaction.state==='ROLLED_BACK'){message.className='restore-warning';message.textContent='Кандидат отклонён; предыдущие binary и SQLite восстановлены как одна пара.'}else if(transaction.state==='ROLLBACK_FAILED'){message.className='restore-warning';message.textContent='Критично: автоматический rollback не завершён. Gateway должен оставаться fail-closed до ручной диагностики.'}else{message.className='restore-warning';message.textContent='Транзакция не достигла терминального состояния; boot recovery должен завершить её автоматически.'}box.append(message,summary)}catch(err){state.cache.signedUpdateStatus=null;const unavailable=document.createElement('p');unavailable.className='restore-warning';unavailable.textContent=`Состояние root-транзакции недоступно: ${err.message}`;box.append(unavailable)}return box}
function resetUserPasswordDialog(user){const dialog=document.createElement('dialog');dialog.className='editor-dialog';const form=document.createElement('form');form.className='card settings-form';form.innerHTML='<h2>Сбросить пароль</h2><p class="muted">Все активные сессии пользователя будут отозваны. Новый пароль станет временным и потребует обязательной замены при следующем входе.</p><label>Новый временный пароль<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></label><label>Повторите пароль<input name="confirmation" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></label><div class="actions"><button type="submit">Сбросить и отозвать сессии</button></div>';const cancel=actionButton('Отмена',()=>dialog.close());form.querySelector('.actions').append(cancel);form.addEventListener('submit',async event=>{event.preventDefault();const password=form.elements.password.value,confirmation=form.elements.confirmation.value;if(password!==confirmation){notice('Пароль и подтверждение не совпадают');return}if(!confirm(`Сбросить пароль пользователя ${user.username} и отозвать все его сессии?`))return;const submit=form.querySelector('button[type="submit"]');submit.disabled=true;try{await api(`/api/v1/auth/users/${encodeURIComponent(user.id)}/password`,{method:'PUT',body:JSON.stringify({password,password_confirmation:confirmation})});dialog.close();notice(`Пароль ${user.username} сброшен; при следующем входе потребуется его замена`);await renderSystemWithDiagnostics()}catch(err){notice(err.message);submit.disabled=false}});dialog.append(form);dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal()}
async function accessManagementPanel(){const [users,sessions]=await Promise.all([api('/api/v1/auth/users'),api('/api/v1/auth/sessions')]);const section=document.createElement('section');section.className='security-access';const box=document.createElement('div');box.className='card';const heading=document.createElement('h2');heading.textContent='Пользователи и активные сессии';const intro=document.createElement('p');intro.className='muted';intro.textContent='В MVP все включённые локальные пользователи являются администраторами. Полноценный RBAC не заявлен. Текущего и последнего активного администратора отключить нельзя; перед удалением пользователя нужно отключить.';const create=document.createElement('form');create.className='settings-form user-create';create.innerHTML='<h3>Добавить администратора</h3><label>Имя пользователя<input name="username" autocomplete="off" minlength="3" maxlength="64" pattern="[A-Za-z0-9][A-Za-z0-9._-]{2,63}" required></label><label>Временный пароль<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></label><label>Повторите пароль<input name="confirmation" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></label><button type="submit">Добавить</button>';create.addEventListener('submit',async event=>{event.preventDefault();const username=create.elements.username.value,password=create.elements.password.value,confirmation=create.elements.confirmation.value;if(password!==confirmation){notice('Пароль и подтверждение не совпадают');return}const submit=create.querySelector('button');submit.disabled=true;try{await api('/api/v1/auth/users',{method:'POST',body:JSON.stringify({username,password,password_confirmation:confirmation})});create.reset();notice(`Пользователь ${username} создан с обязательной заменой временного пароля`);await renderSystemWithDiagnostics()}catch(err){notice(err.message);submit.disabled=false}});const userRows=users.items.map(user=>({...user,status:user.enabled?badge('ENABLED'):badge('DISABLED'),passwordState:user.must_change_password?'Требуется замена':'Постоянный',actions:actionGroup(actionButton('Переименовать',async()=>{const username=prompt('Новое имя пользователя',user.username);if(username===null||username.trim()===user.username)return;await api(`/api/v1/auth/users/${encodeURIComponent(user.id)}`,{method:'PATCH',body:JSON.stringify({username})});notice('Имя пользователя обновлено');await renderSystemWithDiagnostics()}),actionButton(user.enabled?'Отключить':'Включить',async()=>{if(user.enabled&&!confirm(`Отключить ${user.username} и отозвать все его сессии?`))return;await api(`/api/v1/auth/users/${encodeURIComponent(user.id)}`,{method:'PATCH',body:JSON.stringify({enabled:!user.enabled})});notice(user.enabled?'Пользователь отключён; его сессии отозваны':'Пользователь включён');await renderSystemWithDiagnostics()},false,user.id===state.userId),actionButton('Сбросить пароль',()=>resetUserPasswordDialog(user),false,user.id===state.userId),actionButton('Удалить',async()=>{if(!confirm(`Безвозвратно удалить отключённого пользователя ${user.username}?`))return;await api(`/api/v1/auth/users/${encodeURIComponent(user.id)}`,{method:'DELETE',headers:{'X-Confirm-Destructive':'delete-disabled-user'}});notice('Отключённый пользователь удалён');await renderSystemWithDiagnostics()},true,user.enabled||user.id===state.userId))}));const userTable=table([{label:'Пользователь',key:'username'},{label:'Состояние',render:user=>user.status},{label:'Пароль',key:'passwordState'},{label:'Активные сессии',key:'active_sessions'},{label:'Создан',render:user=>new Date(user.created_at).toLocaleString()},{label:'Действия',render:user=>user.actions}],userRows);const sessionsHeading=document.createElement('h3');sessionsHeading.textContent='Активные сессии';const sessionRows=sessions.items.map(session=>({...session,sessionLabel:`${session.id.slice(0,12)}…`,currentLabel:session.current?'Текущая':'Другая',actions:actionGroup(actionButton('Отозвать',async()=>{if(!confirm(session.current?'Отозвать текущую сессию и выйти?':`Отозвать сессию пользователя ${session.username}?`))return;await api(`/api/v1/auth/sessions/${encodeURIComponent(session.id)}`,{method:'DELETE'});if(session.current){showLogin();return}notice('Сессия отозвана');await renderSystemWithDiagnostics()},true))}));const sessionTable=table([{label:'ID',key:'sessionLabel'},{label:'Пользователь',key:'username'},{label:'Тип',key:'currentLabel'},{label:'Последняя активность',render:session=>new Date(session.last_seen_at).toLocaleString()},{label:'Истекает',render:session=>new Date(session.expires_at).toLocaleString()},{label:'',render:session=>session.actions}],sessionRows);box.append(heading,intro,create,userTable,sessionsHeading,sessionTable);section.append(box,ownPasswordForm(false));return section}
async function watchdogPanel(){const [settings,runtime]=await Promise.all([api('/api/v1/settings/watchdog'),api('/api/v1/system/watchdog')]);const policy=settings.policy,limits=settings.limits||{},box=document.createElement('section');box.className='card watchdog-panel';const heading=document.createElement('h2');heading.textContent='Самоконтроль 24/7';const intro=document.createElement('p');intro.className='muted';intro.textContent='Supervisor проверяет только фиксированные компоненты Gateway VPN. Потеря операторов, подписок, targets, VPS или глобального Интернета отображается отдельно и никогда сама по себе не вызывает restart либо reboot.';const current=runtime.status||{},summary=document.createElement('div');summary.className='grid watchdog-summary';summary.append(card('Локальное состояние',runtime.runtime_state==='AVAILABLE'?current.overall_state:'UNAVAILABLE','Процессы, SQLite, firewall и ресурсы'),card('Глобальный доступ',runtime.runtime_state==='AVAILABLE'?current.connectivity_state:'UNKNOWN',current.connectivity_class||'Отдельно от local recovery'),card('Maintenance',current.maintenance?'ACTIVE':'INACTIVE',current.maintenance_code||'Recovery не вмешивается в транзакции'),card('Reboot budget',`${current.host_reboots_24h||0} / ${policy.max_reboots_per_24h}`,current.pending_reboot_at?`Ожидает: ${current.pending_reboot_at}`:'Нет ожидающей перезагрузки'));box.append(heading,intro,summary);if(runtime.runtime_state!=='AVAILABLE'){const warning=document.createElement('p');warning.className='restore-warning';warning.textContent='Runtime status supervisor пока недоступен. Базовые systemd restart и firewall guard продолжают действовать; проверьте unit gateway-vpn-watchdog.';box.append(warning)}else{const componentRows=(runtime.components||[]).map(component=>({...component,stateBadge:badge(component.state),lastSuccess:component.last_success_at||'—',lastFailure:component.last_failure_at||'—',lastRecovery:component.last_recovery_at?`${component.last_recovery_action||'RECOVERY'} · ${component.last_recovery_at}`:'—',suppression:component.recovery_suppressed?(component.suppression_reason||'SUPPRESSED'):'—'}));box.append(table([{label:'Компонент',key:'label'},{label:'Состояние',render:item=>item.stateBadge},{label:'Ошибки подряд',key:'consecutive_failures'},{label:'Успехи подряд',key:'consecutive_successes'},{label:'Restart / window',key:'restarts_in_window'},{label:'Последний успех',key:'lastSuccess'},{label:'Последняя ошибка',key:'lastFailure'},{label:'Recovery',key:'lastRecovery'},{label:'Suppression',key:'suppression'}],componentRows))}const form=document.createElement('form');form.className='settings-form watchdog-editor';const title=document.createElement('h3');title.textContent='Политика восстановления';form.append(title);const check=(labelText,name,value)=>{const label=document.createElement('label');label.className='check';const input=document.createElement('input');input.type='checkbox';input.name=name;input.checked=Boolean(value);label.append(input,document.createTextNode(labelText));form.append(label);return input};const numeric=(labelText,name,value,min,max)=>{const label=document.createElement('label');label.textContent=labelText;const input=document.createElement('input');input.type='number';input.name=name;input.value=value;input.min=min;input.max=max;input.required=true;label.append(input);form.append(label);return input};check('Включить автоматический bounded recovery','enabled',policy.enabled);check('Перед restart запросить idempotent reconcile','reconcile_enabled',policy.reconcile_enabled);check('Разрешить restart только фиксированных компонентов','component_restart_enabled',policy.component_restart_enabled);numeric('Интервал проверки, секунд','check_interval_seconds',policy.check_interval_seconds,limits.check_interval_seconds_min||5,limits.check_interval_seconds_max||300);numeric('Ошибок до recovery','failure_threshold',policy.failure_threshold,limits.failure_threshold_min||1,limits.failure_threshold_max||10);numeric('Успехов до подтверждения восстановления','success_threshold',policy.success_threshold,limits.success_threshold_min||1,limits.success_threshold_max||10);numeric('Cooldown restart, секунд','restart_cooldown_seconds',policy.restart_cooldown_seconds,limits.restart_cooldown_seconds_min||5,limits.restart_cooldown_seconds_max||3600);numeric('Restart одного компонента за окно','max_restarts_per_component',policy.max_restarts_per_component,limits.max_restarts_per_component_min||1,limits.max_restarts_per_component_max||20);numeric('Окно restart budget, секунд','restart_window_seconds',policy.restart_window_seconds,limits.restart_window_seconds_min||60,limits.restart_window_seconds_max||86400);const advanced=document.createElement('fieldset');advanced.className='settings-group watchdog-reboot';const legend=document.createElement('legend');legend.textContent='Аварийная перезагрузка host — advanced';advanced.append(legend);const rebootLabel=document.createElement('label');rebootLabel.className='check';const reboot=document.createElement('input');reboot.type='checkbox';reboot.name='host_reboot_enabled';reboot.checked=Boolean(policy.host_reboot_enabled);rebootLabel.append(reboot,document.createTextNode('Разрешить host reboot только при устойчивом локальном critical failure'));advanced.append(rebootLabel);const advancedNumeric=(labelText,name,value,min,max)=>{const label=document.createElement('label');label.textContent=labelText;const input=document.createElement('input');input.type='number';input.name=name;input.value=value;input.min=min;input.max=max;input.required=true;label.append(input);advanced.append(label)};advancedNumeric('Непрерывный critical до reboot, секунд','reboot_after_critical_seconds',policy.reboot_after_critical_seconds,limits.reboot_after_critical_seconds_min||300,limits.reboot_after_critical_seconds_max||86400);advancedNumeric('Максимум reboot за 24 часа','max_reboots_per_24h',policy.max_reboots_per_24h,limits.max_reboots_per_24h_min||1,limits.max_reboots_per_24h_max||3);advancedNumeric('Grace перед reboot, секунд','reboot_grace_seconds',policy.reboot_grace_seconds,limits.reboot_grace_seconds_min||10,limits.reboot_grace_seconds_max||600);const rebootWarning=document.createElement('p');rebootWarning.className='restore-warning';rebootWarning.textContent='По умолчанию выключено. Внешний outage и pressure диска/памяти не являются причиной reboot. История budget сохраняется после restart и изменения настроек.';advanced.append(rebootWarning);form.append(advanced);const submit=document.createElement('button');submit.type='submit';submit.textContent='Сохранить watchdog policy';form.append(submit);form.addEventListener('submit',async event=>{event.preventDefault();if(reboot.checked&&!policy.host_reboot_enabled&&!confirm('Включить аварийный reboot host? Он сработает только после устойчивого локального critical failure, fail-closed и в пределах durable budget.'))return;const number=name=>Number(form.elements[name].value),payload={enabled:form.elements.enabled.checked,check_interval_seconds:number('check_interval_seconds'),failure_threshold:number('failure_threshold'),success_threshold:number('success_threshold'),reconcile_enabled:form.elements.reconcile_enabled.checked,component_restart_enabled:form.elements.component_restart_enabled.checked,restart_cooldown_seconds:number('restart_cooldown_seconds'),max_restarts_per_component:number('max_restarts_per_component'),restart_window_seconds:number('restart_window_seconds'),host_reboot_enabled:reboot.checked,reboot_after_critical_seconds:number('reboot_after_critical_seconds'),max_reboots_per_24h:number('max_reboots_per_24h'),reboot_grace_seconds:number('reboot_grace_seconds')};submit.disabled=true;try{await api('/api/v1/settings/watchdog',{method:'PUT',body:JSON.stringify(payload)});notice('Watchdog policy сохранена; durable budgets не сброшены');await renderSystemWithDiagnostics()}catch(err){notice(err.message);submit.disabled=false}});box.append(form);return box}
async function renderSystemWithDiagnostics(){await renderSystem();const content=$('content'),history=await signedUpdateTransactionPanel(),signed=await signedUpdatePanel(),updateStatus=state.cache.signedUpdateStatus;if(updateStatus&&updateStatus.staging_query_state!=='AVAILABLE'){signed.querySelector('form')?.remove();const warning=document.createElement('p');warning.className='restore-warning';warning.textContent=updateStatus.staging_query_state==='NOT_CONFIGURED'?'Проверка и загрузка release не настроены.':'Staging journal недоступен; новая загрузка заблокирована до восстановления его целостности.';signed.append(warning)}content.prepend(await accessManagementPanel());content.prepend(history);content.prepend(signed);content.prepend(await backupSnapshotPanel());content.prepend(await diagnosticBundlePanel());content.prepend(await watchdogPanel())}
function renderPlaceholder(tab){const box=document.createElement('div');box.className='card';const h=document.createElement('h2');h.textContent=titles[tab];const p=document.createElement('p');p.className='muted';p.textContent='Раздел подключён к общей структуре Web UI. Runtime-данные появятся после настройки соответствующего системного компонента.';box.append(h,p);setContent(box)}
async function renderSubscriptions(){const [subs,matrix,access]=await Promise.all([api('/api/v1/subscriptions'),api('/api/v1/paths/matrix'),api('/api/v1/access-methods')]);const methodBySubscription=new Map(access.items.filter(item=>item.subscription_id).map(item=>[item.subscription_id,item]));const openEditor=item=>{const dialog=document.createElement('dialog');dialog.className='editor-dialog';const close=()=>dialog.close();dialog.append(subscriptionSettingsForm(item,async()=>{close();await renderSubscriptions()},close));dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal()};const pathStatuses=item=>{const paths=matrix.items.filter(cell=>cell.subscription_id===item.id);const box=document.createElement('div');box.className='path-list';if(!paths.length){box.classList.add('muted');box.textContent='Нет настроенных модемов';return box}paths.forEach(path=>{const line=document.createElement('div');line.append(document.createTextNode(`#${path.modem_number} ${path.modem_name}: `),badge(path.state));box.append(line)});return box};const rows=subs.items.map(item=>{const method=methodBySubscription.get(item.id);return{...item,paths:pathStatuses(item),accessPriority:method?.priority??'—',actions:actionGroup(actionButton('Изменить',()=>openEditor(item)),actionButton(item.enabled?'Отключить':'Включить',async()=>{await api(`/api/v1/access-methods/${encodeURIComponent(method.id)}`,{method:'PATCH',body:JSON.stringify({enabled:!item.enabled})});notice(item.enabled?'Подписка исключена из пользовательского выбора':'Подписка включена и будет проверена');await renderSubscriptions()},false,!method),actionButton('Обновить и проверить',async()=>{const result=await api(`/api/v1/subscriptions/${encodeURIComponent(item.id)}/refresh`,{method:'POST'});notice(result.joined?`Уже выполняется операция ${result.operation_id}`:`Обновление поставлено в очередь: ${result.operation_id}`);await operationDetailsDialog(result.operation_id);await renderSubscriptions()}),actionButton('Удалить',async()=>{if(!confirm(`Удалить отключённую подписку #${item.number} «${item.name}» вместе с сохранёнными версиями?`))return;await api(`/api/v1/subscriptions/${encodeURIComponent(item.id)}`,{method:'DELETE',headers:{'X-Confirm-Destructive':'delete-disabled-subscription'}});notice('Подписка и её защищённые файлы удалены');await renderSubscriptions()},true,item.enabled))}});const heading=document.createElement('div');heading.className='card subscriptions-heading';const title=document.createElement('h2');title.textContent='Настроенные подписки';const note=document.createElement('p');note.className='muted';note.textContent='Общий порядок вместе с «Прямым интернетом» меняется во вкладке «Способы доступа». Обновление разрешено отдельно от участия подписки в пользовательском выборе.';const bulk=actionButton('Обновить все подписки',async()=>{const result=await api('/api/v1/subscriptions/refresh',{method:'POST'});notice(`Принято операций: ${result.accepted.length}; отклонено: ${result.rejected.length}`);if(result.accepted[0])await operationDetailsDialog(result.accepted[0].operation_id)});heading.append(title,note,bulk);setContent(subscriptionSettingsForm(null,renderSubscriptions),heading,table([{label:'№',key:'number'},{label:'Общий приоритет',key:'accessPriority'},{label:'Подписка',key:'name'},{label:'Включена для пользователей',render:item=>item.enabled?'Да':'Нет'},{label:'Обновление',render:item=>item.auto_refresh?`Авто · ${item.refresh_interval_seconds} сек`:'Вручную'},{label:'Fallback ко всем',render:item=>item.fallback_when_named_candidates_fail?'Да':'Нет'},{label:'Состояние',render:item=>badge(item.status)},{label:'LKG',render:item=>item.active_version_id||'—'},{label:'Последний успех',render:item=>item.last_success_at||'—'},{label:'Доступ через модемы',render:item=>item.paths},{label:'Действия',render:item=>item.actions}],rows))}
const renderers={overview:renderOverview,modems:renderModems,access:renderAccessMethods,subscriptions:renderSubscriptions,matrix:renderMatrix,targets:renderTargets,matchers:renderMatchers,nodes:renderNodes,health:renderEvents,traffic:renderTraffic,remote:renderRemote,network:renderNetwork,system:renderSystemWithDiagnostics};
async function selectTab(tab){state.tab=tab;$('page-title').textContent=titles[tab];document.querySelectorAll('#navigation button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));try{await(renderers[tab]||(()=>renderPlaceholder(tab)))()}catch(err){notice(err.message);renderPlaceholder(tab)}}
function notice(message){const el=$('notice');el.textContent=message;el.hidden=!message}
$('login-form').addEventListener('submit',async e=>{e.preventDefault();$('login-error').textContent='';const data=new FormData(e.target);try{const result=await api('/api/v1/auth/login',{method:'POST',body:JSON.stringify({username:data.get('username'),password:data.get('password')})});applySession(result);const reconnect=sessionStorage.getItem('gateway-vpn-update-reconnect')||sessionStorage.getItem('gateway-vpn-restore-reconnect')||'';sessionStorage.removeItem('gateway-vpn-update-reconnect');sessionStorage.removeItem('gateway-vpn-restore-reconnect');if(state.mustChangePassword)showMandatoryPasswordChange();else{showApp();await selectTab('overview')}if(reconnect)notice(`${reconnect} Reconciliation выполняется автоматически; PATH_ACTIVE появится только после повторных проверок.`)}catch(err){$('login-error').textContent=err.message}});
$('navigation').addEventListener('click',e=>{const button=e.target.closest('button[data-tab]');if(button)selectTab(button.dataset.tab)});
$('logout').addEventListener('click',async()=>{try{await api('/api/v1/auth/logout',{method:'POST'})}finally{showLogin()}});
(async()=>{try{const session=await api('/api/v1/auth/session');applySession(session);const reconnect=sessionStorage.getItem('gateway-vpn-update-reconnect')||sessionStorage.getItem('gateway-vpn-restore-reconnect')||'';sessionStorage.removeItem('gateway-vpn-update-reconnect');sessionStorage.removeItem('gateway-vpn-restore-reconnect');if(state.mustChangePassword)showMandatoryPasswordChange();else{showApp();await selectTab('overview')}if(reconnect)notice(reconnect)}catch{showLogin()}})();
